<?php
namespace qqworld_collector\module\translate; use qqworld_collector\lib; class edit extends lib { public function init() { if (!$this->options->qc_translate_enabled) return; foreach ($this->options->qc_translate_post_types as $post_type) { $screen_id = $post_type == 'attachment' ? 'upload' : 'edit-'.$post_type; add_filter( "bulk_actions-{$screen_id}", array($this, 'add_bulk_actions') ); add_filter( "handle_bulk_actions-{$screen_id}", array($this, 'handle_bulk_actions'), 10, 3 ); } $args = array( 'public' => 1, 'show_ui' => 1 ); $taxonomies = get_taxonomies($args); foreach ($taxonomies as $taxonomy) { $screen_id = 'edit-' . $taxonomy; add_filter( "bulk_actions-{$screen_id}", array($this, 'add_taxonomies_bulk_actions') ); add_filter( "handle_bulk_actions-{$screen_id}", array($this, 'handle_taxonomies_bulk_actions'), 10, 3 ); } add_action( 'admin_notices', array($this, 'admin_notices') ); } public function add_bulk_actions($actions) { $actions['translate-post'] = __('Translate', $this->text_domain); return $actions; } public function handle_bulk_actions( $redirect_to, $doaction, $post_ids ) { switch ($doaction) { case 'translate-post': foreach ( $post_ids as $post_id ) { $data = get_post($post_id, ARRAY_A); if (!empty($this->options->qc_translate_automatic_content)) { foreach ($this->options->qc_translate_automatic_content as $content) { if (!empty($data[$content])) { $data[$content] = $this->core->translate($data[$content], '', '', $this->options->qc_translate_mode); } } wp_update_post($data); } } $redirect_to = add_query_arg( 'bulk_translate_post', count( $post_ids ), $redirect_to ); break; } return $redirect_to; } public function add_taxonomies_bulk_actions($actions) { $actions['translate-term-title'] = __('Translate Term Title', $this->text_domain); return $actions; } public function handle_taxonomies_bulk_actions($redirect_to, $doaction, $term_ids) { switch ($doaction) { case 'translate-term-title': foreach ( $term_ids as $term_id ) { $term = get_term($term_id); $term->name = $this->core->translate($term->name, '', '', $this->options->qc_translate_mode); wp_update_term($term_id, $term->taxonomy, array('name' => $term->name)); } $redirect_to = add_query_arg( 'bulk_translate_term_title', count( $term_ids ), $redirect_to ); break; } return $redirect_to; } public function admin_notices() { if ( ! empty( $_REQUEST['bulk_translate_term_title'] ) ) { $hanler_count = intval( $_REQUEST['bulk_translate_term_title'] ); printf( '<div id="message" class="updated fade"><p>' . _n( 'Translated %s term title.', 'Translated %s term titles.', $hanler_count, $this->text_domain) . '</p></div>', $hanler_count ); } elseif ( ! empty( $_REQUEST['bulk_translate_post'] ) ) { $hanler_count = intval( $_REQUEST['bulk_translate_post'] ); printf( '<div id="message" class="updated fade"><p>' . _n( 'Translated %s post.', 'Translated %s posts.', $hanler_count, $this->text_domain) . '</p></div>', $hanler_count ); } } } ?>